// === Daily Content Topic Generator ===
// Rotates through content categories to ensure diverse output

const today = new Date();
const dayOfWeek = today.getDay(); // 0=Sun, 1=Mon, ..., 6=Sat
const dateStr = today.toISOString().split('T')[0];

// Content templates by category - rotate through the week
const weeklyTopics = [
  // Sunday: family & estate
  [
    {
      category: 'family_finance',
      content_type: 'case_study',
      prompt_topic: '一个美国华人家庭因为没有足够人寿保险保障，在意外发生后面临的财务困境。请编写一个教育性案例故事（虚构但合理），帮助读者理解人寿保险对家庭的重要性。',
      target_audience: '有家庭的中青年华人'
    },
    {
      category: 'life_insurance',
      content_type: 'education',
      prompt_topic: '科普文章：Term Life 和 Whole Life 保险的核心区别是什么？各适合什么样的家庭？用通俗易懂的语言解释，避免术语堆砌。',
      target_audience: '保险新手客户'
    }
  ],
  // Monday: retirement & annuity
  [
    {
      category: 'annuity',
      content_type: 'product_intro',
      prompt_topic: '深入浅出介绍美国年金产品（Annuity）的基本类型：Fixed Annuity、Variable Annuity、Indexed Annuity。它们分别适合什么样的退休规划需求？',
      target_audience: '40-60岁关注退休的客户'
    },
    {
      category: 'retirement',
      content_type: 'education',
      prompt_topic: '美国退休规划101：Social Security、401(k)、IRA 和年金产品如何搭配？为美国华人家庭提供一个简单的退休收入规划框架。',
      target_audience: '中年华人家庭'
    }
  ],
  // Tuesday: client communication
  [
    {
      category: 'life_insurance',
      content_type: 'client_communication',
      prompt_topic: '写一篇适合保险经纪发给潜在客户的"破冰"文章：为什么每个在美华人家庭都应该认真考虑人寿保险？从文化、家庭责任和财务安全三个角度入手。',
      target_audience: '尚未购买保险的华人家庭'
    },
    {
      category: 'family_finance',
      content_type: 'case_study',
      prompt_topic: '案例分享：一对在美华人夫妇如何通过合理配置人寿保险和年金，实现了子女教育金储备和自身退休保障的双重目标。',
      target_audience: '有子女的华人家庭'
    }
  ],
  // Wednesday: tax & wealth
  [
    {
      category: 'life_insurance',
      content_type: 'education',
      prompt_topic: '人寿保险的税务优势：Cash Value 免税增长、Death Benefit 免所得税、Policy Loan 的灵活运用。用简单案例说明这些税务优势的实际价值。',
      target_audience: '高收入华人家庭'
    },
    {
      category: 'annuity',
      content_type: 'product_intro',
      prompt_topic: '什么是 IUL（Indexed Universal Life）？它如何兼顾保障和投资增长？适合什么样的客户？客观地介绍优缺点。',
      target_audience: '对投资型保险感兴趣的客户'
    }
  ],
  // Thursday: risk awareness
  [
    {
      category: 'family_finance',
      content_type: 'education',
      prompt_topic: '家庭风险管理清单：作为在美华人，你的家庭保障是否有这些漏洞？从人寿保险、医疗保险、伞险（Umbrella）、长期护理等多维度帮读者自检。',
      target_audience: '所有华人家庭'
    },
    {
      category: 'life_insurance',
      content_type: 'client_communication',
      prompt_topic: '写一篇温暖而不煽情的文章：为什么"年轻"和"健康"正是购买人寿保险的最佳理由？帮助年轻华人客户理解尽早规划的经济优势。',
      target_audience: '25-35岁年轻华人'
    }
  ],
  // Friday: market trends
  [
    {
      category: 'industry_news',
      content_type: 'education',
      prompt_topic: '2024-2025年美国人寿保险市场趋势解读：利率环境变化对保险产品的影响，以及华人客户应如何应对。',
      target_audience: '关注市场的客户'
    },
    {
      category: 'annuity',
      content_type: 'case_study',
      prompt_topic: '退休收入案例：一位60岁华人如何通过年金产品创建可持续的退休月收入流？从实际数字出发，让读者直观理解年金的价值。',
      target_audience: '接近退休的客户'
    }
  ],
  // Saturday: lifestyle & culture
  [
    {
      category: 'family_finance',
      content_type: 'client_communication',
      prompt_topic: '中美保险观念差异：为什么在中国觉得"不吉利"的人寿保险，在美国却是家庭财务规划的基石？从文化角度帮助华人客户转变观念。',
      target_audience: '新移民华人家庭'
    },
    {
      category: 'retirement',
      content_type: 'education',
      prompt_topic: '在美华人的"养老焦虑"：不能完全依赖子女，Social Security 可能不够，如何用保险和年金产品构建属于自己的退休安全网？',
      target_audience: '中老年华人'
    }
  ]
];

const todaysTopics = weeklyTopics[dayOfWeek];

return todaysTopics.map(topic => ({
  json: {
    ...topic,
    generate_date: dateStr,
    day_of_week: ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][dayOfWeek]
  }
}));

// === Parse AI generated content for library ===
const items = $input.all();
const results = [];

for (const item of items) {
  let aiOutput;
  try {
    let text = item.json.text || item.json.message?.content || '';
    text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    aiOutput = JSON.parse(text);
  } catch (e) {
    aiOutput = {
      zh_title: '(解析失败) 请人工审核',
      zh_summary: '内容生成异常',
      zh_content_html: '<p>AI 内容生成失败，请重试或人工编写。</p>',
      category: 'uncategorized',
      content_type: 'unknown',
      image_prompt: 'professional financial planning concept, warm office environment',
      tags: ['待审核'],
      target_audience: '通用'
    };
  }

  const imageUrl = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(aiOutput.image_prompt || 'insurance concept illustration');

  results.push({
    json: {
      zh_title: aiOutput.chinese_title || aiOutput.zh_title,
      zh_summary: aiOutput.chinese_summary || aiOutput.zh_summary,
      zh_content_html: aiOutput.chinese_content_html || aiOutput.zh_content_html,
      category: aiOutput.category,
      content_type: aiOutput.content_type,
      tags: (aiOutput.tags || []).join(', '),
      target_audience: aiOutput.target_audience,
      image_prompt: aiOutput.image_prompt,
      image_url: imageUrl,
      generate_date: new Date().toISOString().split('T')[0],
      publish_date: new Date().toISOString(),
      status: 'pending_review',
      source: 'ai_generated'
    }
  });
}

return results;
